    'ينشئ «إنشاء الاشتراكات المستحقة» المطالبات المستحقة حتى اليوم لجميع الأعضاء المعيَّنين – ولا يكرّرها أبدًا.',
  '„Ich → Einstellungen → Einladen“ oder im Team „Person zur Mannschaft einladen“: persönlich per E-Mail oder als Mannschafts-Link bzw. QR-Code zum Selbstregistrieren. Bei Links gibst du neue Anfragen frei, bevor jemand die App nutzen kann.':
    '«أنا ← الإعدادات ← دعوة» أو من الفريق «دعوة شخص إلى الفريق»: شخصيًا عبر البريد الإلكتروني أو برابط الفريق أو رمز QR للتسجيل الذاتي. عند استخدام الروابط توافق على الطلبات الجديدة قبل أن يتمكن أي شخص من استخدام التطبيق.',
  '„Mannschaft bearbeiten → Spielplan importieren“: CSV-Datei aus dem DFBnet wählen, Vorschau prüfen (neu, geändert, unverändert, übersprungen) und übernehmen. Die Mannschaft bekommt eine Sammelmeldung. Ein erneuter Import aktualisiert Verlegungen, statt Spiele doppelt anzulegen. Innerhalb von 24 Stunden kannst du den Import rückgängig machen.':
    '«تعديل الفريق ← استيراد جدول المباريات»: اختر ملف CSV من DFBnet، وراجع المعاينة (جديد، معدَّل، دون تغيير، متخطّى) ثم اعتمده. يتلقى الفريق إشعارًا مجمّعًا. يحدّث الاستيراد المتكرر المواعيد المؤجلة بدل إنشاء المباريات مرتين. يمكنك التراجع عن الاستيراد خلال 24 ساعة.',
  '„Team → Kader → Mannschaft bearbeiten“: Spieler aus der Vereinsliste hinzufügen oder aus dem Kader nehmen, Funktion (Spieler, Co-Trainer, Betreuer) und Rückennummer ändern, den Kassenwart bestimmen. Unten stellst du ein, wie viele Minuten vor Spielen und Trainings ihr euch trefft, den Standard-Treffpunkt und die Schreibweisen eurer Mannschaft im DFBnet. Co-Trainer haben dieselben Rechte wie der Trainer.':
    '«الفريق ← التشكيلة ← تعديل الفريق»: أضف لاعبين من قائمة النادي أو أزلهم من التشكيلة، وغيّر الوظيفة (لاعب، مدرب مساعد، مشرف) ورقم القميص، وعيّن أمين الصندوق. في الأسفل تضبط عدد الدقائق التي تجتمعون فيها قبل المباريات والتدريبات، ومكان اللقاء الافتراضي، وكتابة اسم فريقكم في DFBnet. للمدربين المساعدين الصلاحيات نفسها التي للمدرب.',
  '„Team → Kasse → Kassenverwaltung“. Dort liegen als Kacheln: Einnahme/Ausgabe, Einzahlungen, Strafe vergeben, Getränke-Strichliste, Umlage, Beiträge, Buchungen & Storno, Kassenwart, Bezahlinfos und Kassenprüfung.':
    '«الفريق ← الصندوق ← إدارة الصندوق». تجد هناك البلاطات التالية: إيراد/مصروف، الإيداعات، تسجيل غرامة، قائمة المشروبات، التقسيم، الاشتراكات، القيود والإلغاء، أمين الصندوق، معلومات الدفع ومراجعة الصندوق.',
  '„Team → Termin anlegen“: Training, Spiel oder Mannschaftstermin. Spiele bekommen die Art Liga, Pokal oder Testspiel. Zum Wiederholen wählst du „Wöchentlich bis …“ und das Enddatum (bis zu etwa einem Jahr). Die Treffzeit berechnet die App aus den Regeln deiner Mannschaft; im einzelnen Termin kannst du sie überschreiben. Im Termin änderst du mit „Termin bearbeiten“ einzelne Termine oder „diesen und folgende“. Mit „Termin absagen“ wird die Mannschaft sofort benachrichtigt.':
    '«الفريق ← إنشاء موعد»: تدريب أو مباراة أو موعد للفريق. تحصل المباريات على نوع: دوري أو كأس أو مباراة ودية. للتكرار اختر «أسبوعيًا حتى …» وتاريخ الانتهاء (حتى سنة تقريبًا). يحسب التطبيق وقت اللقاء من قواعد فريقك، ويمكنك تغييره في الموعد نفسه. في الموعد تعدّل بواسطة «تعديل الموعد» مواعيد منفردة أو «هذا الموعد وما يليه». عند «إلغاء الموعد» يتم إشعار الفريق فورًا.',
