    'يرى زملاء الفريق أيضًا سبب الاعتذار أو الغياب (مثل إصابة أو مرض).',
  'Auch ohne Werbung bleibt der Sponsor in der Übersicht sichtbar.':
    'يظل الراعي ظاهرًا في النظرة العامة حتى دون إعلان.',
  'Audit-Log einsehen': 'عرض سجل التدقيق',
  'Auf der letzten Seite findest du die passenden Schaltflächen.':
    'تجد الأزرار المناسبة في الصفحة الأخيرة.',
  'Auf der Startseite und unter „Verein → News“. Dringende Meldungen stehen oben und erreichen dich auch per Push. Mit „Gefällt mir“ und Kommentaren kannst du reagieren.':
    'في الصفحة الرئيسية وضمن «النادي ← الأخبار». تظهر الإشعارات العاجلة في الأعلى وتصلك أيضًا كإشعارات فورية. يمكنك التفاعل بـ«إعجاب» وتعليقات.',
  'Auf die Forderung wurde schon gezahlt. Storniere zuerst die Buchung im Kassenbuch.':
    'تم الدفع على هذه المطالبة بالفعل. ألغِ القيد أولًا في دفتر الصندوق.',
  'Auf jeder Unterseite siehst du oben deinen Weg, zum Beispiel „Team › Kasse › Strafenkatalog“. Tippe auf eine frühere Stufe, um dorthin zurückzugehen, oder auf den runden Pfeil für einen Schritt zurück. Bei langen Wegen steht „…“ für die ausgelassenen Stufen; ein Tipp zeigt sie als Liste. Die untere Leiste bleibt sichtbar, der aktuelle Bereich ist markiert.':
    'في كل صفحة فرعية ترى مسارك في الأعلى، مثل «الفريق › الصندوق › قائمة الغرامات». اضغط على مستوى سابق للعودة إليه، أو على السهم الدائري للرجوع خطوة. في المسارات الطويلة تدل «…» على المستويات المحذوفة؛ والضغط عليها يعرضها كقائمة. يبقى الشريط السفلي ظاهرًا ويكون المجال الحالي مميّزًا.',
  'Auf Konto': 'على الحساب',
  'auf später verschoben': 'تم التأجيل إلى وقت لاحق',
  'Auf Start und unter Termine sagst du zu oder ab. Mit „Rückgängig“ nimmst du es gleich wieder zurück.':
    'في الرئيسية وضمن المواعيد تؤكد حضورك أو تعتذر. وبـ«تراجع» يمكنك إلغاء ذلك فورًا.',
