  'Aus Vereinsliste': 'من قائمة النادي',
  'Aus: Jede Person sieht nur die eigenen Beträge. Kassenstand, Einnahmen und Ausgaben sieht immer die ganze Mannschaft.':
    'إيقاف: يرى كل شخص مبالغه فقط. أما رصيد الصندوق والإيرادات والمصروفات فيراها الفريق كله دائمًا.',
