  'Beginnt am {0}. Kader planst du unter Verwaltung → Mitglieder: Mannschaften der neuen Saison sind dort mit „(Saison {1})“ gekennzeichnet.':
    'تبدأ في {0}. تخطط التشكيلات ضمن الإدارة ← الأعضاء: فرق الموسم الجديد مميّزة هناك بـ«(موسم {1})».',
  Begründung: 'السبب',
  'Begründung (bei Ablehnung)': 'السبب (عند الرفض)',
  'Begründung für das Storno': 'سبب الإلغاء',
  'Begünstigter Zweck': 'الغرض المستفيد',
  'Bei Auswärtsspielen und Turnieren gibt es im Termin den Bereich „Fahrgemeinschaften“. Tippe auf „Ich fahre“ und gib die freien Plätze an, oder wähle bei einem Auto „Mitfahren“. Wer keine Mitfahrt hat, tippt auf „Mitfahrt suchen“. Eltern buchen für ihre Kinder.':
    'في المباريات خارج الأرض والبطولات يوجد في الموعد قسم «مشاركة السيارات». اضغط «سأقود» وحدّد المقاعد الشاغرة، أو اختر «مرافقة» عند إحدى السيارات. ومن ليس لديه توصيلة يضغط «البحث عن توصيلة». يحجز أولياء الأمور لأطفالهم.',
  'Bei der Anmeldung schicken wir dir einen 6-stelligen Code per E-Mail (10 Minuten gültig, nur einmal nutzbar). Sicherer ist eine Authenticator-App – der E-Mail-Code ist die einfachere Alternative.':
    'عند تسجيل الدخول نرسل لك رمزًا من 6 أرقام عبر البريد الإلكتروني (صالح 10 دقائق ويُستخدم مرة واحدة فقط). تطبيق المصادقة أكثر أمانًا – ورمز البريد الإلكتروني هو البديل الأسهل.',
  'Bei dir': 'عندك',
  'Bei Dubletten': 'عند وجود مكرّرات',
  'Bei einer Absage ist ein Grund Pflicht': 'ذكر السبب إلزامي عند الاعتذار',
  'Bei Spielen fehlt der Gegner.': 'الخصم مفقود في المباريات.',
  'bei Spielen Pflicht': 'إلزامي للمباريات',
  'Bei Terminen fehlt der Titel.': 'العنوان مفقود في المواعيد.',
  'bei Terminen Pflicht, sonst automatisch': 'إلزامي للمواعيد، وإلا فتلقائي',
  'Bei Terminen siehst du die Antwort für jede Person. Zu- und Absagen gelten je Kind.':
    'في المواعيد ترى رد كل شخص. تأكيدات الحضور والاعتذارات تنطبق على كل طفل.',
  'Bei Vereinsveranstaltungen (z. B. Jahreshauptversammlung, Turnier) kannst du Zusagen, Absagen oder „Unsicher“ wählen – ohne Begründung. Zusätzlich gibt es oft „Helfer gesucht“: Trage dich in eine Schicht ein.':
    'في فعاليات النادي (مثل الجمعية العمومية أو البطولة) يمكنك اختيار تأكيد الحضور أو الاعتذار أو «غير متأكد» – دون ذكر سبب. وغالبًا يوجد أيضًا «مطلوب مساعدون»: سجّل نفسك في مناوبة.',
  beidfüßig: 'بكلتا القدمين',
  Beidfüßig: 'بكلتا القدمين',
  'Beim Austritt werden alle Mannschaftszuordnungen beendet, Rollen entzogen und der App-Zugang gesperrt. Die Daten bleiben für die Vereinsunterlagen erhalten.':
    'عند الانسحاب تنتهي جميع تعيينات الفرق، وتُسحب الأدوار، ويُقفل الوصول إلى التطبيق. تبقى البيانات محفوظة لسجلات النادي.',
  'Beim Buchen einer Einnahme wählst du den Sponsor aus (Verein → Sponsoren).':
    'عند تسجيل إيراد تختار الراعي (النادي ← الرعاة).',
  'Beim Eigentor des Gegners gibt es keinen Torschützen.':
    'لا يوجد هدّاف عند تسجيل الخصم هدفًا في مرماه.',
  'Beim Kassenwart oder Trainerteam': 'لدى أمين الصندوق أو الطاقم التدريبي',
  'Beim Löschen werden die automatischen Absagen zurückgenommen. Bei Mannschaften mit aktiver Zu-/Absage ist die Rückmeldung danach wieder offen.':
    'عند الحذف تُسحب الاعتذارات التلقائية. وفي الفرق ذات التأكيد/الاعتذار الفعّال يصبح الرد مفتوحًا من جديد بعد ذلك.',
  'Beim Planen einer Veranstaltung wählst du oben die Gruppe („Ganzer Verein“, eine Abteilung …). Mit „Mannschaften oder Personen auswählen“ lädst du gezielt ein: Setze im Fenster Häkchen bei Mannschaften oder suche Personen. Die Auswahl erscheint als Chips; mit „×“ nimmst du jemanden wieder heraus. Nur die Eingeladenen werden benachrichtigt. Einzelne Personen darfst du nur mit dem Recht für die Mitgliederliste einladen.':
    'عند تخطيط فعالية تختار المجموعة في الأعلى («النادي كله»، قسم …). وبـ«اختيار فرق أو أشخاص» تدعو بشكل محدد: ضع علامات على الفرق في النافذة أو ابحث عن أشخاص. يظهر الاختيار على شكل شارات؛ وبـ«×» تزيل أي شخص. يُشعَر المدعوون فقط. لا يمكنك دعوة أشخاص منفردين إلا بصلاحية قائمة الأعضاء.',
  'Beim Start und nach einer Minute im Hintergrund fragt die App nach Face ID, Fingerabdruck oder dem Gerätecode. Die Einstellung gilt nur auf diesem Gerät.':
    'عند التشغيل وبعد دقيقة في الخلفية يطلب التطبيق Face ID أو بصمة الإصبع أو رمز الجهاز. يسري هذا الإعداد على هذا الجهاز فقط.',
