    'حضّر الموسم القادم: ستُنقل جميع الفرق مع وحداتها ومهلها وأطقمها التدريبية ومهامها الإضافية (مثل أمين الصندوق). يبقى الموسم الحالي دون تغيير حتى تبدأ الموسم الجديد.',
