  'Das Konto': 'الحساب',
  'Das Konto gehört dem Kind. Ihr könnt die Stufe jederzeit senken; wieder erhöhen geht nur mit Zustimmung des Kindes.':
    'الحساب ملك للطفل. يمكنكم خفض المستوى في أي وقت؛ أما رفعه مجددًا فلا يمكن إلا بموافقة الطفل.',
  'Das Konto ist archiviert.': 'الحساب مؤرشف.',
  'Das Kürzel „{0}“ ist in dieser Saison vergeben.': 'الاختصار «{0}» مستخدم في هذا الموسم.',
  'Das Kürzel (2 bis 4 Zeichen, z. B. „SGW“) steht groß im Plakat der Startseite und ersetzt das Wappen, solange kein Logo hochgeladen ist. Die Vereinsadministration ändert es unter „Verwaltung → Verein & Design“, mit Vorschau. Die Vibration bei Auswahl und Bestätigung schaltest du auf dem Handy unter „Ich → Konto & Einstellungen → Vibration“ aus; bei eingestellter „Bewegung reduzieren“ des Geräts bleiben auch die Animationen aus.':
    'يظهر الاختصار (من 2 إلى 4 أحرف، مثل «SGW») بحجم كبير في لافتة الصفحة الرئيسية ويحل محل الشعار ما دام لم يُرفع شعار. يغيّره مسؤول النادي ضمن «الإدارة ← النادي والتصميم» مع معاينة. تعطّل الاهتزاز عند الاختيار والتأكيد على الهاتف ضمن «أنا ← الحساب والإعدادات ← الاهتزاز»؛ وإذا كان خيار «تقليل الحركة» مفعّلًا في الجهاز فتتوقف الحركات المتحركة أيضًا.',
  'Das Kürzel besteht aus 2 bis 4 Buchstaben oder Ziffern.':
    'يتكون الاختصار من 2 إلى 4 أحرف أو أرقام.',
  'Das Kürzel steht groß im Plakat auf der Startseite und ersetzt das Wappen, solange kein Logo hochgeladen ist.':
    'يظهر الاختصار بحجم كبير في لافتة الصفحة الرئيسية ويحل محل الشعار ما دام لم يُرفع شعار.',
  'Das laufende Jahr kann erst nach seinem Ende abgeschlossen werden.':
    'لا يمكن إغلاق السنة الجارية إلا بعد انتهائها.',
  'Das Logo erscheint oben in der App bei allen Mitgliedern.':
    'يظهر الشعار في أعلى التطبيق لدى جميع الأعضاء.',
