  'Das sieht nur die Kassenführung des ganzen Vereins.':
    'لا يرى ذلك إلا إدارة الصندوق على مستوى النادي كله.',
  'Das sind alle Termine.': 'هذه كل المواعيد.',
  'Das sind optionale Funktionen, die dein Verein einschalten kann: Fundbüro & Marktplatz für Gesuchtes und Gefundenes, ein kleines Forum für wenige Themen und Vereinswissen mit Artikeln wie „Wo gibt es den Schlüssel?“. Sie erscheinen nur, wenn sie aktiv sind.':
    'هذه وظائف اختيارية يمكن لناديك تفعيلها: مكتب المفقودات والسوق للمطلوب والموجود، ومنتدى صغير لعدد قليل من المواضيع، ومعرفة النادي مع مقالات مثل «أين المفتاح؟». لا تظهر إلا إذا كانت مفعّلة.',
