  'Der Termin': 'الموعد',
  'Der Termin gehört nicht zu dieser Mannschaft.': 'الموعد لا ينتمي إلى هذا الفريق.',
  'Der Termin gehört nicht zur Mannschaft.': 'الموعد لا ينتمي إلى الفريق.',
  'Der Termin hat schon begonnen.': 'بدأ الموعد بالفعل.',
  'Der Termin ist bereits abgesagt.': 'الموعد ملغى بالفعل.',
