  'Der Termin liegt in der Vergangenheit.': 'الموعد في الماضي.',
  'Der Termin wurde abgesagt.': 'تم إلغاء الموعد.',
  'Der Untergrund je Platz hilft bei der Planung, z. B. wenn Rasenplätze gesperrt sind.':
    'يساعد نوع الأرضية لكل ملعب في التخطيط، مثلًا عند إغلاق الملاعب العشبية.',
  'Der Verband setzt dich bei fremden Spielen ein. Trage den Einsatz hier ein, damit er in deinem Kalender steht und Überschneidungen mit deinen Terminen auffallen.':
    'يعيّنك الاتحاد في مباريات الآخرين. سجّل المهمة هنا لتظهر في تقويمك وتنكشف أي تداخلات مع مواعيدك.',
  'Der Verein braucht mindestens einen Fulladmin.': 'يحتاج النادي إلى مسؤول كامل واحد على الأقل.',
  'Der Verein ist bereits eingerichtet.': 'النادي معدّ بالفعل.',
  'Der Verein kann mehrere Kassen führen, z. B. eine Jugendkasse. Unter „Admin-Verwaltung → Verein → Abteilungen“ legst du Abteilungen an (z. B. Senioren, Frauen, Jugend); danach fragt die App, ob die Abteilung eine eigene Kasse bekommen soll. Unter „Kassen“ legst du Kassen an, ordnest sie einer oder mehreren Abteilungen zu und bestimmst genau eine Hauptkasse. Ohne eigene Kasse laufen die Buchungen einer Abteilung über die Hauptkasse. Jede Kasse hat eigene Konten und Beiträge; in der Vereinskasse wechselst du oben zwischen „Alle“ und einer einzelnen Kasse. Kassen werden nie gelöscht, nur stillgelegt. Eine Umbuchung zwischen Konten verschiedener Kassen wird in beiden Kassen gebucht, ein Storno wirkt in beiden. Die Rolle Kassenwart (Verein) kann für den ganzen Verein oder nur für eine Abteilung vergeben werden und gilt dann nur für deren Kassen.':
    'يمكن للنادي إدارة عدة صناديق، مثل صندوق للشباب. ضمن «إدارة المشرفين ← النادي ← الأقسام» تنشئ الأقسام (مثل الكبار والسيدات والشباب)؛ ثم يسأل التطبيق إن كان القسم سيحصل على صندوق خاص. ضمن «الصناديق» تنشئ الصناديق وتعيّنها لقسم واحد أو أكثر وتحدد صندوقًا رئيسيًا واحدًا بالضبط. من دون صندوق خاص تتم قيود القسم عبر الصندوق الرئيسي. لكل صندوق حساباته واشتراكاته الخاصة؛ وفي صندوق النادي تتنقل في الأعلى بين «الكل» وصندوق واحد. لا تُحذف الصناديق أبدًا بل تُوقَف فقط. يُسجَّل التحويل بين حسابات صناديق مختلفة في كلا الصندوقين، ويسري الإلغاء في كليهما. يمكن منح دور أمين الصندوق (النادي) للنادي كله أو لقسم واحد فقط، ويسري حينها على صناديقه فقط.',
  'Der Verein verlangt für deine Rolle die 2-Faktor-Anmeldung.':
    'يشترط النادي تسجيل الدخول بخطوتين لدورك.',
  'Der Verein verlangt für die Verwaltung die 2-Faktor-Anmeldung. Bitte unter „Konto & Sicherheit“ einrichten.':
    'يشترط النادي تسجيل الدخول بخطوتين للإدارة. يرجى إعداده ضمن «الحساب والأمان».',
  'Der Verein verlangt sie für deine Verwaltungsrechte. Bis dahin ist die Verwaltung gesperrt.':
    'يشترطها النادي لصلاحياتك الإدارية. حتى ذلك الحين تبقى الإدارة مقفلة.',
  'Der Vermerk': 'الملاحظة',
  'Der Vermerk wird entfernt.': 'سيتم حذف الملاحظة.',
  'Der Verwendungszweck fehlt.': 'الغرض من الدفع مفقود.',
  'Der volle Name steht auf Dokumenten, der Kurzname in der Kopfzeile und auf dem Wappen.':
    'يظهر الاسم الكامل في المستندات، والاسم المختصر في الترويسة وعلى الشعار.',
  'Der Vorstand sieht – wenn der Verein es in „Einsicht“ freigibt – unter „Verein → Vereinsleben → Kassenübersicht“ eine reine Anzeige: Kassenstand gesamt, Einnahmen und Ausgaben, die einzelnen Kassen und die Beitragsquote. Buchungen, Belege und Funktionen gibt es dort nicht; die Vereinskasse selbst führen Kassenwart und Kassenprüfer.':
    'إذا أتاح النادي ذلك في «الاطلاع»، يرى مجلس الإدارة ضمن «النادي ← حياة النادي ← نظرة عامة على الصندوق» عرضًا فقط: إجمالي رصيد الصندوق، والإيرادات والمصروفات، والصناديق الفردية ونسبة سداد الاشتراكات. لا توجد هناك قيود أو إيصالات أو وظائف؛ أما صندوق النادي نفسه فيديره أمين الصندوق ومراجعو الصندوق.',
  'Der Vorstand sieht auch Kassenbuch und Belege (ohne zu buchen)':
    'يرى مجلس الإدارة أيضًا دفتر الصندوق والإيصالات (دون تسجيل قيود)',
  'Der Vorstand sieht Kontostände und Summen, aber keine einzelnen Buchungen':
    'يرى مجلس الإدارة أرصدة الحسابات والمجاميع، لكن لا يرى القيود الفردية',
