  'Die Nominierung': 'الترشيح',
  'Die Nummern unten sind Vorschläge; in der Aufstellung kannst du sie je Spiel ändern.':
    'الأرقام أدناه اقتراحات؛ ويمكنك تغييرها لكل مباراة في التشكيلة الأساسية.',
  'Die Passwörter stimmen nicht überein.': 'كلمتا المرور غير متطابقتين.',
  'Die Person': 'الشخص',
  'Die Person gehört nicht zur Mannschaft.': 'الشخص لا ينتمي إلى الفريق.',
