  'Die Rolle wird archiviert und kann wiederhergestellt werden.':
    'سيتم أرشفة الدور ويمكن استعادته.',
  'Die Rollenübersicht ist für Vorstand und Administration.':
    'نظرة الأدوار العامة مخصصة لمجلس الإدارة والإدارة.',
  'Die Rücklage': 'الاحتياطي',
  'Die Rücklage ist aufgelöst.': 'تم حل الاحتياطي.',
  'Die Rücklage ist noch nicht leer. Entnimm zuerst den Rest.':
    'الاحتياطي ليس فارغًا بعد. اسحب الباقي أولًا.',
  'Die Rückmeldung konnte nicht gespeichert werden.': 'تعذّر حفظ الرد.',
  'Die Saison {0} ist bereits vorbereitet.': 'موسم {0} جاهز بالفعل.',
  'Die Saison lässt sich später in der Verwaltung wechseln.':
    'يمكن تغيير الموسم لاحقًا في الإدارة.',
  'Die Schicht': 'المناوبة',
  'Die Schiedsrichter-Übersicht sehen Schiedsrichter und Verantwortliche.':
    'يرى الحكام والمسؤولون نظرة الحكام العامة.',
  'Die Schiedsrichterverwaltung ist im Verein nicht aktiviert.':
    'إدارة الحكام غير مفعّلة في النادي.',
  'Die Spende': 'التبرع',
  'Die Spende wird als Einnahme im Kassenbuch gebucht. Mit ausgestellter Bestätigung kann die Buchung nicht mehr storniert werden.':
    'يُسجَّل التبرع كإيراد في دفتر الصندوق. وبعد إصدار الإفادة لا يمكن إلغاء القيد.',
  'Die Sperrung': 'الإغلاق',
  'Die Sperrung konnte nicht angelegt werden.': 'تعذّر إنشاء الإغلاق.',
  'Die Sperrung wird aufgehoben.': 'سيتم رفع الإغلاق.',
  'Die Steuerdaten des Vereins sind noch nicht vollständig. Die Administration trägt sie ein und gibt die Vorlage nach rechtlicher Prüfung frei.':
    'البيانات الضريبية للنادي غير مكتملة بعد. تُدخلها الإدارة وتعتمد القالب بعد المراجعة القانونية.',
  'Die Steuerdaten pflegt die Vereinsadministration.': 'يدير مسؤول النادي البيانات الضريبية.',
  'Die Stimme konnte nicht gespeichert werden.': 'تعذّر حفظ الصوت.',
  'Die Strafe': 'الغرامة',
  'Die Teilnahme': 'المشاركة',
  'Die Teilnehmer sieht nur das Trainerteam.': 'لا يرى المشاركين إلا الطاقم التدريبي.',
  'Die Trainingsplanung ist für die Mannschaft nicht aktiviert.': 'تخطيط التدريب غير مفعّل للفريق.',
  'Die Trainingsplanung ist im Verein nicht aktiviert.': 'تخطيط التدريب غير مفعّل في النادي.',
  'Die Übung': 'التمرين',
  'Die Übungsbibliothek ist für Trainerteams.': 'مكتبة التمارين مخصصة للأطقم التدريبية.',
  'Die Umfrage': 'الاستطلاع',
  'Die Umfrage ist bereits beendet.': 'الاستطلاع منتهٍ بالفعل.',
  'Die Umfrage konnte nicht beendet werden.': 'تعذّر إنهاء الاستطلاع.',
  'Die Umfrage konnte nicht erstellt werden.': 'تعذّر إنشاء الاستطلاع.',
  'Die Veranstaltung': 'الفعالية',
  'Die Veranstaltung liegt in der Vergangenheit.': 'الفعالية في الماضي.',
  'Die Veranstaltung wurde nicht gefunden.': 'لم يتم العثور على الفعالية.',
  'Die Vereinseinstellungen ändert die Vereinsadministration.':
    'يغيّر مسؤول النادي إعدادات النادي.',
  'Die Vereinskasse einrichten': 'إعداد صندوق النادي',
  'Die Vereinskasse führt der Kassenwart (Verein).': 'يدير أمين الصندوق (النادي) صندوق النادي.',
  'Die Vereinskasse führt nur die Kassenführung.': 'لا يدير صندوق النادي إلا إدارة الصندوق.',
  'Die Vereinskasse ist nicht aktiviert.': 'صندوق النادي غير مفعّل.',
  'Die Vereinskasse ist von den Mannschaftskassen getrennt und liegt unter „Verein → Vereinskasse“ (wenn das Modul aktiv ist). Der Kassenwart (Verein) legt Konten mit Anfangsbestand an, bucht Einnahmen und Ausgaben mit Kategorie, optionaler Kostenstelle, Belegnummer und Belegfoto und bucht um zwischen Konten. Buchungen werden nie gelöscht, sondern mit Begründung storniert. Die Kategorien gehören zu den vier steuerlichen Bereichen (ideell, Vermögensverwaltung, Zweckbetrieb, wirtschaftlicher Geschäftsbetrieb). Kassenprüfer lesen alles, buchen aber nicht. Wer außerdem einsehen darf (z. B. der Vorstand), stellt die Vereinsadministration unter „Einrichtung“ ein.':
    'صندوق النادي منفصل عن صناديق الفرق ويوجد ضمن «النادي ← صندوق النادي» (إذا كانت الوحدة مفعّلة). ينشئ أمين الصندوق (النادي) الحسابات برصيد افتتاحي، ويسجّل الإيرادات والمصروفات مع الفئة ومركز تكلفة اختياري ورقم إيصال وصورة إيصال، ويحوّل بين الحسابات. لا تُحذف القيود أبدًا بل تُلغى مع ذكر السبب. تنتمي الفئات إلى المجالات الضريبية الأربعة (معنوي، إدارة الأصول، نشاط غرضي، نشاط تجاري). يقرأ مراجعو الصندوق كل شيء لكنهم لا يسجّلون قيودًا. ومن يحق له الاطلاع أيضًا (مثل مجلس الإدارة) يضبطه مسؤول النادي ضمن «الإعداد».',
  'Die Vereinskasse sehen nur Kassenführung und Prüfer.':
    'لا يرى صندوق النادي إلا إدارة الصندوق والمراجعون.',
  'Die Verwaltung ist für Vorstand, Leitung und Administration.':
    'الإدارة مخصصة لمجلس الإدارة والقيادة والمسؤولين.',
  'Die Vorlage ist noch nicht freigegeben. Sie muss zuerst rechtlich bzw. steuerlich geprüft werden.':
    'القالب لم يُعتمد بعد. يجب أن يخضع أولًا لمراجعة قانونية أو ضريبية.',
  'Die Vorlage mit Beispielzeile und Spaltenerklärung lädst du in der Web-Verwaltung herunter.':
    'تنزّل القالب مع سطر نموذجي وشرح الأعمدة من إدارة الويب.',
  'Die Vorlage muss zuerst rechtlich bzw. steuerlich geprüft und von der Administration freigegeben werden.':
    'يجب أولًا أن يخضع القالب لمراجعة قانونية أو ضريبية وأن تعتمده الإدارة.',
  'Die Vorlage schaltet passende Funktionen für die Mannschaft ein.':
    'يفعّل القالب الوظائف المناسبة للفريق.',
  'Die Werte anderer Spieler sieht nur die Mannschaft.': 'لا يرى قيم اللاعبين الآخرين إلا الفريق.',
  'Die Zeile „{0}“ wird aus dem Haushaltsplan entfernt.': 'سيتم حذف البند «{0}» من الموازنة.',
  'Die Zeit wurde geändert.': 'تم تغيير الوقت.',
  'Die Zugehörigkeit zu „{0}“ wird beendet.': 'سيتم إنهاء الانتماء إلى «{0}».',
  'Die Zuordnung': 'التعيين',
  'Die Zuordnung merkt sich Clubroof für Dateien mit denselben Spaltenüberschriften.':
    'يتذكر Clubroof هذا التعيين للملفات ذات عناوين الأعمدة نفسها.',
  'Die Zuwendungsbestätigung': 'إفادة التبرع',
  'Dies ist ein Platzhalter aus dem Demoverein.': 'هذا نص بديل من النادي التجريبي.',
  'Diese Abteilung darfst du nicht einstellen.': 'لا يحق لك ضبط هذا القسم.',
