  'Ein kurzer Willkommenstext erscheint im Team-Tab – zum Beispiel zu Kleidung, Treffpunkten und Regeln.':
    'يظهر نص ترحيبي قصير في تبويب الفريق – مثلًا عن الملابس وأماكن اللقاء والقواعد.',
  'Ein Mannschafts-Link (oder QR-Code als Aushang) lässt neue Spieler und Eltern eine Beitrittsanfrage stellen. Du gibst jede Anfrage frei. Ein neuer Link macht den alten ungültig.':
    'يتيح رابط الفريق (أو رمز QR كإعلان) للاعبين وأولياء الأمور الجدد تقديم طلب انضمام. وأنت توافق على كل طلب. الرابط الجديد يُبطل القديم.',
  'ein Platz bleibt frei': 'يبقى مقعد واحد شاغرًا',
  'Ein Platz der Formation ist doppelt besetzt.': 'أحد مراكز الخطة مشغول مرتين.',
  'Ein Spieler steht doppelt in der Aufstellung.': 'لاعب مدرج مرتين في التشكيلة الأساسية.',
  'Ein Sponsor passt nur zu einer Einnahme.': 'الراعي يناسب الإيراد فقط.',
  'Ein Team': 'فريق واحد',
  'Ein zusätzlicher Schutz: Nach dem Passwort fragt die App einen Code ab – aus einer Authenticator-App oder per E-Mail (6 Stellen, 10 Minuten gültig, nur einmal nutzbar). Du richtest ihn unter „Ich → Konto & Einstellungen“ ein. Pflicht ist er nur für das Administrationskonto, wenn der Verein es verlangt.':
    'حماية إضافية: بعد كلمة المرور يطلب التطبيق رمزًا – من تطبيق مصادقة أو بالبريد الإلكتروني (6 أرقام، صالح 10 دقائق، يُستخدم مرة واحدة). تُعدّه ضمن «أنا ← الحساب والإعدادات». وهو إلزامي لحساب المسؤول فقط إذا اشترطه النادي.',
