  'Es gibt noch fehlerhafte Zeilen. Bitte korrigieren oder abwählen.':
    'لا تزال هناك أسطر بها أخطاء. يرجى تصحيحها أو إلغاء تحديدها.',
  'Es gibt noch keine Erwachsenen mit Login in der Mannschaft.':
    'لا يوجد بالغون لديهم حساب دخول في الفريق بعد.',
  'Es gibt noch keine Kategorien für diese Art. Lege sie unter „Einrichtung“ an.':
    'لا توجد فئات لهذا النوع بعد. أنشئها ضمن «الإعداد».',
  'Es gibt nur einen Fulladmin – lege einen zweiten an.': 'يوجد مسؤول كامل واحد فقط – أنشئ ثانيًا.',
  'Es gibt zwei Wege: Unter „Ich“ stehen direkt unter deinem Profil die zwei farbigen Knöpfe „Admin-Verwaltung“ (violett) und „Vereinskasse“ (blau) – nur die, für die du Rechte hast. Außerdem steht unter „Verein“ in der Gruppe „Meine Vereinsaufgaben“ der Zugang zur „Verwaltung“ (für alle mit Verwaltungsrechten) und zur „Vereinskasse“ (für alle mit Kassenzugriff); am Desktop stehen beide dauerhaft in der Seitenleiste. Beide öffnen einen eigenen Bereich mit farbigem Kopfband und „Zur App“ oben sowie einer Leiste mit Reitern unten. Die Verwaltung hat die Reiter Übersicht, Mitglieder, Sport, Inhalte und Verein – du siehst nur, wofür du Rechte hast. In der Vereinskasse gibt es Übersicht, Buchung, Beiträge, Planung und Auswertung. Funktionen mit „Bald verfügbar“ folgen in einem späteren Update.':
    'هناك طريقتان: ضمن «أنا» تجد مباشرة تحت ملفك الشخصي الزرين الملونين «إدارة المشرفين» (بنفسجي) و«صندوق النادي» (أزرق) – فقط ما لديك صلاحيات له. وضمن «النادي» في مجموعة «مهامي في النادي» تجد الوصول إلى «الإدارة» (لكل من لديه صلاحيات إدارية) وإلى «صندوق النادي» (لكل من لديه وصول إلى الصندوق)؛ وعلى الحاسوب يظهر كلاهما دائمًا في الشريط الجانبي. يفتح كل منهما مجالًا خاصًا بشريط علوي ملوّن وزر «إلى التطبيق» في الأعلى وشريط تبويبات في الأسفل. للإدارة التبويبات: نظرة عامة، الأعضاء، الرياضة، المحتوى والنادي – وترى فقط ما لديك صلاحيات له. وفي صندوق النادي: نظرة عامة، القيود، الاشتراكات، التخطيط والتقارير. الوظائف المعلَّمة «متاح قريبًا» ستأتي في تحديث لاحق.',
  'Es ist ein unerwarteter Fehler aufgetreten.': 'حدث خطأ غير متوقع.',
