  Gelesen: 'مقروء',
  'Gelöscht – lässt sich wiederherstellen': 'محذوف – يمكن استعادته',
  'Gelöschte Einträge liegen hier und lassen sich wiederherstellen. Endgültig gelöscht wird nie automatisch, sondern nur auf deinen Anstoß.':
    'تبقى الإدخالات المحذوفة هنا ويمكن استعادتها. لا يتم الحذف النهائي تلقائيًا أبدًا، بل بمبادرة منك فقط.',
  'Gelöschte Rollen': 'الأدوار المحذوفة',
  'Gelöschte Rollen lassen sich wiederherstellen.': 'يمكن استعادة الأدوار المحذوفة.',
  'Gelöschte Wissensartikel, Übungen, Aufgaben, Sponsoren, Dokumente und ausgemustertes Material landen im Archiv; bei Dokumenten bleibt die Datei erhalten, bis das Archiv bereinigt wird. Das Trainerteam öffnet das Archiv seiner Mannschaft unter „Team → Archiv“ (gelöschte Aufgaben und Dokumente, wiederherstellen). Die Administration öffnet das ganze Archiv unter „Verwaltung → Abo & Kontrolle → Archiv“: Dort stellst du einen Eintrag mit „Wiederherstellen“ wieder her. Ist sein Name inzwischen vergeben, fragt dich die App nach einem neuen Namen. Endgültig gelöscht wird nie automatisch: „Bereinigen“ entfernt, was älter als die Standardfrist ist (derzeit 2 Jahre), „Archiv leeren“ löscht alles; beides nur auf deinen Anstoß und mit Bestätigung. „Archiv exportieren“ speichert alle archivierten Einträge als Datei.':
    'تنتقل مقالات المعرفة والتمارين والمهام والرعاة والمستندات والمعدات المستبعدة المحذوفة إلى الأرشيف؛ وفي المستندات يبقى الملف محفوظًا حتى يُنظَّف الأرشيف. يفتح الطاقم التدريبي أرشيف فريقه ضمن «الفريق ← الأرشيف» (المهام والمستندات المحذوفة، استعادة). وتفتح الإدارة الأرشيف كاملًا ضمن «الإدارة ← الاشتراك والرقابة ← الأرشيف»: هناك تستعيد أي إدخال بـ«استعادة». إذا أصبح اسمه مستخدمًا يطلب منك التطبيق اسمًا جديدًا. لا يتم الحذف النهائي تلقائيًا أبدًا: «تنظيف» يزيل ما هو أقدم من المدة الافتراضية (حاليًا سنتان)، و«إفراغ الأرشيف» يحذف كل شيء؛ وكلاهما بمبادرة منك فقط ومع تأكيد. «تصدير الأرشيف» يحفظ جميع الإدخالات المؤرشفة كملف.',
