  'Je Sponsor': 'لكل راعٍ',
  'Jede Änderung setzt die Freigabe der Vorlage zurück.': 'كل تغيير يعيد ضبط اعتماد القالب.',
  'Jede Kasse hat eigene Konten, Beiträge und Auswertung. Ohne Zuordnung läuft eine Abteilung über die Hauptkasse. Der Jahresabschluss gilt immer für den ganzen Verein.':
    'لكل صندوق حساباته واشتراكاته وتقاريره. وبدون إسناد يعمل القسم عبر الصندوق الرئيسي. أما الإقفال السنوي فيسري دائمًا على النادي كله.',
  'Jede Leitung sieht nur Daten ihrer Abteilung': 'كل إدارة ترى بيانات قسمها فقط',
  'Jede Mannschaft legt fest, bis wann Zu- und Absagen möglich sind. Der Countdown steht am Termin („Frist: Noch 2 Tage“). Danach bleibt deine Antwort sichtbar (Schloss „Frist abgelaufen“), ändern kann sie nur dein Trainerteam.':
    'يحدد كل فريق حتى متى يمكن التأكيد أو الاعتذار. ويظهر العد التنازلي عند الموعد («المهلة: متبقٍ يومان»). بعد ذلك يبقى ردك ظاهرًا (قفل «انتهت المهلة») ولا يستطيع تغييره سوى جهازك التدريبي.',
  'Jede Person sagt zu oder ab – der Trainer sieht, wer noch fehlt':
    'كل شخص يؤكد أو يعتذر، ويرى المدرب من لم يرد بعد',
  'Jede Zeile ist grün (neu), blau (aktualisiert), gelb (Dublette) oder rot (Fehler). Abgewählte Zeilen werden nicht übernommen.':
    'كل سطر أخضر (جديد) أو أزرق (محدَّث) أو أصفر (مكرر) أو أحمر (خطأ). الأسطر غير المحددة لا تُعتمد.',
  'Jeder Spieler behält seine Nummer; sie erscheint im Kader und in der Aufstellung.':
    'يحتفظ كل لاعب برقمه؛ ويظهر في التشكيلة وفي التشكيلة الأساسية.',
  'Jeder Spieler der Startelf braucht einen Platz der Formation.':
    'كل لاعب في التشكيل الأساسي يحتاج إلى مركز في الخطة.',
  'Jedes Feld kann nur einer Spalte zugeordnet werden.': 'يمكن إسناد كل حقل إلى عمود واحد فقط.',
  'Jedes Mitglied reicht unter „Verein → Auslage einreichen“ Kosten mit Beleg (Foto) oder Fahrtkosten ein – bei Fahrtkosten rechnet die App aus den Kilometern (30 Cent je km). Der Kassenwart sieht die Auslagen unter „Vereinskasse → Buchung → Auslagen“, genehmigt oder lehnt mit Begründung ab und erstattet: Dabei entsteht eine Ausgabe im Kassenbuch. Du bekommst zu jedem Schritt eine Benachrichtigung. Eine erstattete Auslage kann nicht storniert werden.':
    'يقدّم كل عضو من «النادي ← تقديم نفقة» تكاليف مع إيصال (صورة) أو مصاريف سفر، وفي مصاريف السفر يحسب التطبيق من الكيلومترات (30 سنتًا للكيلومتر). يرى أمين الصندوق النفقات في «صندوق النادي ← قيد ← النفقات»، ويوافق أو يرفض مع ذكر السبب ثم يسدد: وبذلك ينشأ مصروف في دفتر الصندوق. يصلك إشعار عند كل خطوة. لا يمكن إلغاء نفقة تم سدادها.',
  'Jetzt einrichten': 'إعداد الآن',
  'Jetzt starten': 'ابدأ الآن',
