  'Kassenbuchung erfasst': 'تم تسجيل قيد الصندوق',
  Kassenprüfer: 'مدقق الصندوق',
  'Kassenprüfer beginnen unter „Vereinskasse → Auswertung → Kassenprüfung“ eine Prüfung für ein Jahr – für den ganzen Verein oder nur für ihre Kasse. Die App zieht auf Wunsch zufällige Stichproben; jede Buchung wird abgehakt oder mit Begründung beanstandet, den Beleg siehst du direkt. Dazu kommen freie Vermerke. Sind alle Stichproben erledigt, gibst du den Prüfbericht mit deinem Ergebnis ab; danach ist er nicht mehr änderbar und dient als Grundlage der Entlastung. Die Kassenführung sieht abgegebene Berichte (auch als PDF oder CSV). Prüfer buchen nicht, der Kassenwart prüft nicht.':
    'يبدأ مدققو الصندوق من «صندوق النادي ← التقارير ← تدقيق الصندوق» تدقيقًا لسنة، للنادي كله أو لصندوقهم فقط. يسحب التطبيق عند الطلب عينات عشوائية؛ ويُعلَّم كل قيد بالموافقة أو يُعترض عليه مع ذكر السبب، وترى الإيصال مباشرة. وتضاف إليها ملاحظات حرة. عند الانتهاء من كل العينات تسلّم تقرير التدقيق مع نتيجتك؛ وبعدها لا يمكن تغييره ويُعتمد أساسًا لإبراء الذمة. ترى إدارة الصندوق التقارير المسلَّمة (كذلك بصيغة PDF أو CSV). المدققون لا يسجلون قيودًا، وأمين الصندوق لا يدقق.',
  Kassenprüfung: 'تدقيق الصندوق',
  'Kassenprüfung {0} begonnen': 'بدأ تدقيق الصندوق {0}',
