  'Minderjährig ohne Elternteil und ohne E-Mail – später zuordnen.':
    'قاصر بدون والد/والدة وبدون بريد إلكتروني، يُسند لاحقًا.',
  'Mindestens 10 Zeichen – am besten ein kurzer Satz.': '10 أحرف على الأقل، والأفضل جملة قصيرة.',
  'Mindestens 10 Zeichen. Eine Wortfolge oder ein Satz ist sicherer und leichter zu merken als ein kurzes Passwort mit Sonderzeichen.':
    '10 أحرف على الأقل. سلسلة كلمات أو جملة أكثر أمانًا وأسهل في التذكر من كلمة مرور قصيرة برموز خاصة.',
  'Mindestens eine importierte Person hat schon ein Konto. Der Import lässt sich nicht mehr rückgängig machen.':
    'لدى شخص مستورد واحد على الأقل حساب بالفعل. لم يعد بالإمكان التراجع عن الاستيراد.',
  'Mindestens zwei Buchstaben eingeben.': 'أدخل حرفين على الأقل.',
  'Mini-Forum': 'منتدى مصغّر',
  'Mit Ablaufdatum': 'بتاريخ انتهاء',
  'Mit App-Zugang': 'مع دخول إلى التطبيق',
  'Mit dem Start wird {0} zur laufenden Saison. Mannschaftskassen, Mannschaftsdokumente und künftige Termine gehen auf die neuen Mannschaften über. Zuordnungen und Aufgaben der alten Saison enden. Das lässt sich nicht rückgängig machen.':
    'بالبدء يصبح {0} الموسم الجاري. تنتقل صناديق الفرق ومستنداتها والمواعيد المستقبلية إلى الفرق الجديدة. وتنتهي إسنادات الموسم القديم ومهامه. لا يمكن التراجع عن ذلك.',
  'Mit den Pfeilen verschiebst du das Datum um einen Tag. Tippst du auf das Datum selbst, öffnet sich ein Kalender: Wische oder tippe auf die Pfeile, um den Monat zu wechseln, tippe auf einen Tag zum Auswählen oder wähle „Heute“. Nicht erlaubte Tage sind ausgegraut.':
    'بالأسهم تزيح التاريخ يومًا واحدًا. وإذا نقرت على التاريخ نفسه يُفتح تقويم: اسحب أو انقر على الأسهم لتغيير الشهر، وانقر على يوم لاختياره أو اختر «اليوم». الأيام غير المسموحة باهتة.',
  'Mit den Schreibweisen aus dem DFBnet ordnet der Spielplan-Import die Spiele richtig zu.':
    'بأشكال الكتابة من DFBnet يسند استيراد جدول المباريات المباريات بشكل صحيح.',
  'Mit der Anschrift füllt Clubroof Spendenbescheinigungen aus; die Zeitzone bestimmt Fristen und Terminzeiten.':
    'بالعنوان يملأ Clubroof إيصالات التبرعات؛ وتحدد المنطقة الزمنية المهل وأوقات المواعيد.',
  'Mit der Zwei-Faktor-Anmeldung braucht jede neue Anmeldung zusätzlich einen Code. Für das Administrationskonto empfehlen wir sie.':
    'مع تسجيل الدخول بخطوتين يحتاج كل تسجيل دخول جديد إلى رمز إضافي. ننصح به لحساب الإدارة.',
  'Mit dieser E-Mail-Adresse gibt es bereits ein Konto. Bitte melde dich an oder nutze „Passwort vergessen“.':
    'يوجد حساب بهذا البريد الإلكتروني بالفعل. سجّل الدخول أو استخدم «نسيت كلمة المرور».',
  'Mit dieser E-Mail-Adresse gibt es bereits ein Konto. Das Kind braucht eine eigene Adresse.':
    'يوجد حساب بهذا البريد الإلكتروني بالفعل. يحتاج الطفل إلى عنوان خاص به.',
  'Mit Einladungslink oder Einladungscode (auch per QR-Code scannen) trittst du deinem Verein bei – der Verein wird danach auf diesem Gerät gemerkt. Hast du schon ein Konto, melde dich mit E-Mail und Passwort an („Zeigen“ macht das Passwort sichtbar). Einen neuen Verein richtest du mit dem Einrichtungscode (Format CR-XXXX-XXXX) ein, den du von Clubroof nach Zahlungseingang erhältst; er gilt einmal.':
    'برابط الدعوة أو رمز الدعوة (ويمكن أيضًا مسح رمز QR) تنضم إلى ناديك، ثم يُحفظ النادي على هذا الجهاز. إذا كان لديك حساب فسجّل الدخول بالبريد الإلكتروني وكلمة المرور («إظهار» يُظهر كلمة المرور). أما لإعداد نادٍ جديد فتستخدم رمز الإعداد (بالصيغة CR-XXXX-XXXX) الذي تتلقاه من Clubroof بعد استلام الدفع؛ وهو صالح لمرة واحدة.',
  'Mit Face ID oder Fingerabdruck entsperren': 'فتح القفل ببصمة الوجه أو بصمة الإصبع',
  'Mit festen Trainingszeiten stehen die Termine sofort im Kalender, und Zu- und Absagen funktionieren ab dem ersten Tag.':
    'بأوقات تدريب ثابتة تظهر المواعيد في التقويم فورًا، ويعمل التأكيد والاعتذار منذ اليوم الأول.',
