  'Welche Beitragsarten gibt es? Mit Vorschlägen starten und Beträge anpassen.':
    'ما أنواع الاشتراكات؟ ابدأ بالاقتراحات وعدّل المبالغ.',
  'Welche Daten habt ihr schon? Die Importe laufen nach der Einrichtung, jeweils mit Vorlage, Spaltenzuordnung und Vorschau. Excel-Dateien mit mehreren Blättern gehen auch – du wählst das Blatt aus.':
    'ما البيانات التي لديكم بالفعل؟ تتم عمليات الاستيراد بعد الإعداد، كل منها بقالب وإسناد للأعمدة ومعاينة. وملفات Excel متعددة الأوراق مدعومة أيضًا، وتختار الورقة.',
  'Welche Daten wir verarbeiten': 'البيانات التي نعالجها',
  'Welche Daten wir verarbeiten und warum': 'البيانات التي نعالجها ولماذا',
