  'Zusatzaufgabe: Mannschaftskasse, Buchungen, Strafen/Getränke, Abrechnung':
    'مهمة إضافية: صندوق الفريق، والقيود، والغرامات/المشروبات، والتسوية',
  'Zusätzlich absichern?': 'هل تريد تأمينًا إضافيًا؟',
  'Zusätzlich Vorstand: alles': 'إضافة إلى مجلس الإدارة: كل شيء',
